.tbl td{padding:7px 8px;border-bottom:1px solid #f1f1ee;color:#334155;vertical-align:middle;}
.tbl td.mono,.tbl td .mono{font-family:var(--mono);}
.sev{display:inline-block;font-size:9px;font-weight:700;padding:1px 7px;border-radius:8px;}
